                let data = null;
                for (let i = messages.length - 1; i >= 0; i--) {
                    const msg = messages[i];
                    if (msg && msg.data && msg.data.stat_data) {
                        data = msg.data.stat_data;
                        break;
                    }
                }

                if (!data || !data.当前情景) {
                    console.error("MVU Error: No valid stat_data found in chat history.");
                    document.getElementById('char-name').innerText = "无有效数据";
                    return;
                }

                // 更新日期信息
                updateDateInfo(data);

                // 更新用户信息
                updateUserInfo(data);

                // 更新当前情景
                document.getElementById('char-name').innerText = data.当前情景?.当前客户名[0] || "无客户";
                document.getElementById('objective-text').innerText = data.当前情景?.订单目标[0] || "无订单";
                document.getElementById('location-text').innerText = data.当前情景?.当前位置[0] || "未知位置";

                if (data.客户列表) {
                    customerKeys = Object.keys(data.客户列表);
                    customerList = Object.values(data.客户列表);
                }

                if (customerKeys.length > 0) {
                    const activeCustomerName = data.当前情景?.当前客户名;
                    let activeIndex = customerKeys.indexOf(activeCustomerName);
                    viewedCustomerIndex = (activeIndex !== -1) ? activeIndex : 0;
                    renderCustomer(viewedCustomerIndex);
                }

            } catch (error) {
                console.error("Status Bar Error:", error);
            }
        }

        document.getElementById('next-char').addEventListener('click', () => {
            if (customerList.length === 0) return;
            viewedCustomerIndex = (viewedCustomerIndex + 1) % customerList.length;
            renderCustomer(viewedCustomerIndex);
        });

        document.getElementById('prev-char').addEventListener('click', () => {
            if (customerList.length === 0) return;
            viewedCustomerIndex = (viewedCustomerIndex - 1 + customerList.length) % customerList.length;
            renderCustomer(viewedCustomerIndex);
        });

        document.addEventListener("DOMContentLoaded", initDisplay);
    </script>
